'use strict';
(()=>{
  const API='https://platform-grievance-india.darrin-dookie.chatgpt.site/api/bangladesh/race';
  const NAMES={dialogue:'Call It What It Is',rapport:'Rapport Relay',inclusion:'Inclusion Detective',secretariat:'Secretariat Sprint',delivery:'Decision to Delivery',action:'Action Plan Rescue',mandate:'Whose Table Is It?'};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let events=null,token=null,expiresAt=0,rooms=[],currentRoom='',teams=[],poll=null,busy=false,epoch=0,lastSync=0,serverOffset=0,hidden=false;
  const clock=ms=>{const s=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
  const panel=()=>document.querySelector('#live-board');
  const workshop=()=>panel()?.dataset.workshop||'institutions';
  function message(value,error=false){const el=document.querySelector('#board-notice');if(el){el.textContent=value;el.classList.toggle('error',error);}}
  async function request(action,body,query={}){
    const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);
    try{
      const response=await fetch(API+'?'+new URLSearchParams({action,...query}),{method:body?'POST':'GET',headers:{...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),mode:'cors',credentials:'omit',cache:'no-store',signal:controller.signal});
      let data;try{data=await response.json();}catch{throw new Error('The live service did not return a usable response. Please retry.');}
      if(!response.ok){const error=new Error(data.error||'The live service could not complete this request.');error.status=response.status;throw error;}
      serverOffset=data.serverNow-Date.now();return data;
    }catch(error){if(error.name==='AbortError')throw new Error('The live service timed out. Check your connection and retry.');if(error.name==='TypeError')throw new Error('Could not reach the live board. Check your connection and retry. Your teaching materials are still available.');throw error;}finally{clearTimeout(timeout);}
  }
  async function signIn(username,password){const data=await request('login',{username,password});token=data.token;expiresAt=data.expiresAt;rooms=[];currentRoom='';return true;}
  async function signOut(){stop();const old=token;token=null;expiresAt=0;rooms=[];teams=[];currentRoom='';if(old){try{await fetch(API+'?action=logout',{method:'POST',headers:{Authorization:'Bearer '+old,'Content-Type':'application/json'},body:'{}',mode:'cors',credentials:'omit',keepalive:true});}catch{}}}
  function stop(){events?.abort();events=null;clearInterval(poll);poll=null;epoch++;document.body.classList.remove('board-projector');}
  function roomOptions(){const rows=rooms.filter(r=>r.workshop===workshop());return `<option value="">Choose a session</option>`+rows.map(r=>`<option value="${r.code}" ${r.code===currentRoom?'selected':''}>${esc(r.code)} · ${esc(r.label)} · ${NAMES[r.game]}${r.active?'':' · closed'}</option>`).join('');}
  function loginView(){return `<section class="card"><span class="badge">Live competition service</span><h2 style="margin-top:16px">Connect your live board</h2><p>Your teaching materials are unlocked. Sign in with the same facilitator credentials to reconnect the team controls.</p><form id="board-login" class="code-form"><label class="field">Username<input name="username" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" maxlength="256" required></label><button class="button" type="submit">Connect live board</button></form><p id="board-notice" role="alert" class="error"></p></section>`;}
  function shell(){return `<div class="callout"><strong>One code. One live competition.</strong> Create a session for one workshop and game, then share its code or join link. Use one shared device per team. Scores and progress synchronize across devices; up to 32 teams can join a session.</div><section class="card board-setup"><span class="badge">Start a challenge</span><h2 style="margin-top:16px">Set the room up</h2><form id="create-session" class="session-form"><label class="field">Game<select name="game">${Object.entries(NAMES).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="field">Session label<input name="label" maxlength="70" required placeholder="e.g. Day 2 · Wage evidence" value="${workshop()==='institutions'?'Institutions':'Secretariats'} · workshop challenge"></label><button class="button" type="submit">Create session code →</button></form><label class="field" style="margin-top:22px">Or open an existing session<select id="live-room">${roomOptions()}</select></label></section><p id="board-notice" role="status" aria-live="polite"></p><div id="session-detail"></div>`;}
  function teamOrder(){return [...teams].sort((a,b)=>b.metrics.score-a.metrics.score||elapsed(a)-elapsed(b));}
  const elapsed=t=>Math.max(0,(t.finishedAt||Date.now()+serverOffset)-t.startedAt);
  function gameLink(r){const suffix=new URLSearchParams({w:r.workshop,room:r.code,...(r.game==='dialogue'?{}:{game:r.game})});return new URL((r.game==='dialogue'?'games/dialogue/index.html':'games/challenges/index.html')+'?'+suffix,document.baseURI).href;}
  function detail(){const r=rooms.find(r=>r.code===currentRoom),el=document.querySelector('#session-detail');if(!el)return;if(!r){el.innerHTML='<div class="empty"><h3>Ready when you are</h3><p>Create a session or select one above to see the teams competing.</p></div>';return;}
    el.innerHTML=`<section class="card session-code-card"><div><div class="eyebrow">${esc(r.label)} · ${r.workshop==='institutions'?'Workshop 01':'Workshop 02'}</div><h2>${NAMES[r.game]}</h2><p>Share this eight-character code</p><strong class="session-code">${r.code}</strong><p class="muted">${r.active?'Open to new teams':'Closed to new teams · teams already joined can continue'}</p></div><div class="actions"><button class="button" data-board="copy-code">Copy code</button><button class="button secondary" data-board="copy-link">Copy join link</button><a class="button secondary" href="${esc(gameLink(r))}" target="_blank" rel="noopener">Open participant game ↗</a></div></section><section class="card" style="margin-top:22px"><div class="section-title"><h2>Teams at the table</h2><span id="board-sync" class="source-note"></span></div><div class="actions board-actions"><button class="button small secondary" data-board="refresh">Refresh now</button><button class="button small secondary" data-board="hide">${hidden?'Reveal':'Hide'} scores</button><button class="button small secondary" data-board="project">${document.body.classList.contains('board-projector')?'Exit':'Open'} projector view</button><button class="button small secondary" data-board="export">Export results ↓</button><button class="button small secondary" data-board="close">${r.active?'Close to new teams':'Reopen to new teams'}</button><button class="button small danger" data-board="reset-all" ${!teams.length?'disabled':''}>Reset all teams</button></div><div id="live-team-table">${table()}</div><p class="source-note">${r.game==='dialogue'?'Right/wrong counts form classifications. Points also include the setting and the keyword-guided suggested change.':'Right/wrong counts whole rounds. A partly correct two-choice round counts as wrong and still earns its partial points.'} Rank by points, then elapsed time. “Last activity” reflects server updates. Polling runs every 2.5 seconds; a stale board is flagged.</p></section>`;
    paintSync();
  }
  function table(){if(!teams.length)return '<div class="empty"><h3>Waiting for teams</h3><p>Ask each team to open the selected game, enter an alias and use the session code above.</p></div>';
    return `<div class="table-scroll"><table class="leaderboard live-leaderboard"><thead><tr><th scope="col">Rank</th><th scope="col">Team</th><th scope="col">Question / section</th><th scope="col">Answered</th><th scope="col">Right</th><th scope="col">Wrong</th><th scope="col">Points</th><th scope="col">Time</th><th scope="col">Last activity</th><th scope="col">Controls</th></tr></thead><tbody>${teamOrder().map((t,i)=>{const m=t.metrics,age=Math.max(0,Math.floor((Date.now()+serverOffset-t.updatedAt)/1000));return `<tr><td>${hidden?'—':i+1}</td><th scope="row">${esc(t.name)}<small>Attempt ${t.generation}${m.done?' · finished':''}</small></th><td>${esc(m.stepName)}<small>${m.step} of ${m.steps}</small></td><td>${m.answered} / ${m.steps}</td><td>${hidden?'—':m.correct}</td><td>${hidden?'—':m.wrong}</td><td><strong>${hidden?'—':m.score}</strong> / ${m.max}</td><td>${clock(elapsed(t))}</td><td><span class="activity-dot ${age>20?'quiet':''}"></span>${age<5?'Just now':age+'s ago'}</td><td><button class="button small secondary" data-reset-team="${t.id}" data-team-name="${esc(t.name)}">Reset team</button></td></tr>`;}).join('')}</tbody></table></div>`;
  }
  function paintSync(){const el=document.querySelector('#board-sync');if(el){const age=Math.max(0,Math.floor((Date.now()-lastSync)/1000));el.textContent=lastSync?`Updated ${age<3?'just now':age+'s ago'} · ${teams.length} team${teams.length===1?'':'s'}`:'Connecting…';el.classList.toggle('error',!lastSync||age>10);}}
  async function refresh(loadRooms=false){if(busy||!panel()||!token)return;const ownEpoch=epoch;busy=true;try{if(Date.now()+serverOffset>=expiresAt){token=null;throw new Error('Your live-board login expired. Sign out and unlock again.');}if(loadRooms||!rooms.length){const d=await request('rooms');if(ownEpoch!==epoch)return;rooms=d.rooms;const sel=document.querySelector('#live-room');if(sel)sel.innerHTML=roomOptions();}
      if(currentRoom){const data=await request('board',null,{room:currentRoom});if(ownEpoch!==epoch)return;teams=data.teams;rooms=[data.room,...rooms.filter(r=>r.code!==data.room.code)];lastSync=Date.now();const tableEl=document.querySelector('#live-team-table');if(tableEl)tableEl.innerHTML=table();else detail();paintSync();}message('Live board connected.');
    }catch(error){if(ownEpoch!==epoch)return;if(error.status===401)token=null;message(error.message,true);paintSync();}finally{busy=false;}}
  function mount(){stop();const el=panel();if(!el)return;const w=workshop();if(currentRoom&&!rooms.some(r=>r.code===currentRoom&&r.workshop===w)){currentRoom='';teams=[];}el.innerHTML=token&&Date.now()+serverOffset<expiresAt?shell():loginView();if(token){detail();refresh(true);poll=setInterval(()=>{if(!panel()){stop();return;}refresh();paintSync();},2500);}
    events=new AbortController();
    el.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;try{if(form.id==='board-login'){await signIn(form.elements.username.value,form.elements.password.value);form.elements.password.value='';mount();return;}if(form.id==='create-session'){message('Creating the session…');const d=await request('create',{game:form.elements.game.value,label:form.elements.label.value,workshop:w});rooms.unshift(d.room);currentRoom=d.room.code;teams=[];lastSync=Date.now();document.querySelector('#live-room').innerHTML=roomOptions();detail();message('Session created. Share the code or join link.');}}catch(error){message(error.message,true);}finally{button.disabled=false;}},{signal:events.signal});
    el.addEventListener('change',event=>{if(event.target.id==='live-room'){currentRoom=event.target.value;teams=[];lastSync=0;detail();refresh();}},{signal:events.signal});
    const runBoardAction=async event=>{const b=event.target.closest('button');if(!b||(!b.dataset.board&&!b.dataset.resetTeam))return;const r=rooms.find(r=>r.code===currentRoom);if(!r)return;const action=b.dataset.board;b.disabled=true;try{
        if(action==='refresh')await refresh(true);
        if(action==='copy-code'||action==='copy-link'){const value=action==='copy-code'?r.code:gameLink(r);try{await navigator.clipboard.writeText(value);message(action==='copy-code'?'Session code copied.':'Join link copied.');}catch{message('Copy this '+(action==='copy-code'?'code: ':'join link: ')+value);}}
        if(action==='hide'){hidden=!hidden;detail();}
        if(action==='project'){document.body.classList.toggle('board-projector');detail();}
        if(action==='close'){await request('close',{room:r.code,active:!r.active});r.active=r.active?0:1;detail();document.querySelector('#live-room').innerHTML=roomOptions();message(r.active?'Session reopened.':'Session closed to new teams. Existing teams can continue.');}
        if(action==='reset-all'||b.dataset.resetTeam){const name=action==='reset-all'?`all ${teams.length} teams in ${r.code}`:b.dataset.teamName;if(!confirm(`Reset ${name}? Their points and answers will clear, and connected devices will return to question one. This cannot be undone.`))return;await request(action==='reset-all'?'reset-all':'reset',{room:r.code,...(b.dataset.resetTeam?{teamId:b.dataset.resetTeam}:{})});await refresh();detail();message('Reset saved. Connected teams will restart within a few seconds.');}
        if(action==='export'){const rows=teamOrder(),cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const csv='Rank,Session,Game,Workshop,Team,Question_or_section,Answered,Right,Wrong,Points,Maximum,Time_seconds,Attempt,Finished\r\n'+rows.map((t,i)=>[i+1,r.code,NAMES[r.game],r.workshop,t.name,t.metrics.stepName,t.metrics.answered,t.metrics.correct,t.metrics.wrong,t.metrics.score,t.metrics.max,Math.floor(elapsed(t)/1000),t.generation,t.metrics.done].map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Bangladesh_'+r.code+'_results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('Results exported.');}
      }catch(error){message(error.message,true);}finally{b.disabled=false;}};
    el.addEventListener('click',event=>{if(event.target.closest('button[data-board],button[data-reset-team]'))runBoardAction(event);},{signal:events.signal});
  }
  window.BDLive={signIn,signOut,mount,stop,connected:()=>!!token};
})();
